class Solution {
static const int MOD=1000000007;
int low,high;
int countUpTo(const string& s){int n=s.size();vector<vector<int>> dp(2,vector<int>(high+1));dp[1][0]=1;for(int i=0;i<n;++i){vector<vector<int>> ndp(2,vector<int>(high+1));for(int tight=0;tight<=1;++tight)for(int sum=0;sum<=high;++sum)if(dp[tight][sum]){int lim=tight?s[i]-'0':9;for(int d=0;d<=lim&&sum+d<=high;++d){int &v=ndp[tight&&d==lim][sum+d];v=(v+dp[tight][sum])%MOD;}}dp.swap(ndp);}int ans=0;for(int t=0;t<2;++t)for(int s=low;s<=high;++s)ans=(ans+dp[t][s])%MOD;return ans;}
public:int count(string num1,string num2,int min_sum,int max_sum){low=min_sum;high=max_sum;int a=countUpTo(num2),b=countUpTo(num1);int digitSum=0;for(char c:num1)digitSum+=c-'0';return (a-b+(digitSum>=low&&digitSum<=high)+MOD)%MOD;}
};
